const MARK_ID = '6a732cd00c61629cf1d3c144';
const validId = /^[0-9a-f]{24}$/u;
const ids = new Set();
const addTender = (candidate, path, optionalEmpty = false) => {
  if (candidate == null && optionalEmpty) return;
  if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) throw new Error(`Malformed ${path}: expected tender object`);
  if (typeof candidate.id !== 'string' || !validId.test(candidate.id.trim())) throw new Error(`Malformed tender id at ${path}.id`);
  ids.add(candidate.id.trim());
};
for (const item of $input.all()) {
  const body = item.json;
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Malformed mark relation response');
  const hasTender = Object.hasOwn(body, 'tender');
  const hasTenders = Object.hasOwn(body, 'tenders');
  if (!hasTender && !hasTenders) throw new Error('Malformed mark relation response: missing tender/tenders');
  if (hasTender) addTender(body.tender, 'tender', true);
  if (hasTenders) {
    if (!Array.isArray(body.tenders)) throw new Error('Malformed tenders: expected array');
    body.tenders.forEach((candidate, index) => addTender(candidate, `tenders[${index}]`));
  }
}
return [...ids].sort().map((tender_id) => ({ json: { trigger_kind: 'tenderplan_mark', manual_override: false, tender_id, source_event_key: `tenderplan:mark:${MARK_ID}:tender:${tender_id}` } }));
